  "quests:q_goblin_slayer:description": "Repila ainda mais a horda goblin: mate 30 Goblins nas Terras da Fronteira, outrora a muralha-escudo do Confim.",
  "quests:q_goblin_slayer:name": "Algoz de Goblins",
