  "campBuildings:camp_tavern:name": "A Taverna",
  "campBuildings:camp_tavern:description": "Halvard serviu a primeira rodada antes mesmo do telhado ficar pronto. Notícias viajam mais rápido sobre uma caneca cheia.",
  "items:black_market_crate_i:name": "Caixa do Mercado Negro I",
  "items:black_market_crate_i:description": "Uma caixa que trocou de mãos mais de uma vez antes de chegar até você. Ninguém pergunta o que tem dentro até ela ser aberta.",
  "items:black_market_crate_ii:name": "Caixa do Mercado Negro II",
  "items:black_market_crate_ii:description": "Mais pesada que a anterior, e os pregos são novos. Alguém queria que parecesse comum.",
  "items:black_market_crate_iii:name": "Caixa do Mercado Negro III",
  "items:black_market_crate_iii:description": "Selada com um carimbo que significa algo numa cidade que você nunca visitou.",
  "items:black_market_crate_iv:name": "Caixa do Mercado Negro IV",
  "items:black_market_crate_iv:description": "Ela chacoalhou uma vez no caminho até aqui e nunca mais. É melhor abri-la em algum lugar tranquilo.",
  "items:black_market_crate_v:name": "Caixa do Mercado Negro V",
  "items:black_market_crate_v:description": "O Forasteiro não quis dizer quem embalou esta. Só isso já deveria dizer algo.",
  "tavernGuests:halvard:role": "Estalajadeiro",
  "tavernGuests:halvard:greeting": "Sente-se. Quem senta aqui, fala. Quem fala, fica.",
  "tavernGuests:viktor:greeting": "Os abutres estão ficando ousados. Vinte cabeças, e eu pago.",
  "tavernGuests:billy:role": "Fazendeiro",
  "tavernGuests:billy:greeting": "Meus canteiros estão cheios e só tenho duas mãos.",
  "tavernGuests:grumm:role": "Minerador",
  "tavernGuests:grumm:greeting": "Metal não mente. Quarenta minérios, e conversamos.",
  "tavernGuests:brakka:role": "Lenhadora",
  "tavernGuests:brakka:greeting": "Mole demais. Traga algo mais duro.",
  "tavernGuests:nessa:role": "Pescadora",
  "tavernGuests:nessa:greeting": "A maré tira, a maré dá. Hoje ela dá. Aproveite.",
  "tavernGuests:tamsin:role": "Coletora",
  "tavernGuests:tamsin:greeting": "A velha diz que eu devia aprender paciência. Me ajude a trapacear.",
  "tavernGuests:ilvara:role": "Herborista",
  "tavernGuests:ilvara:greeting": "A floresta lembra receitas que todos vocês esqueceram.",
  "tavernGuests:odo:role": "Cozinheiro",
  "tavernGuests:odo:greeting": "A guarda come carne crua. Isso é uma vergonha. Me ajude.",
  "tavernGuests:dashk:role": "Ferreiro",
  "tavernGuests:dashk:greeting": "Urga diz que o aço escuta a paciência. Eu não tenho nenhuma. E você?",
  "tavernGuests:merrit:role": "Armeira",
  "tavernGuests:merrit:greeting": "Uma lâmina sem fio é um pedaço de pau cheio de desculpas.",
  "tavernGuests:kell:role": "Curtidor",
  "tavernGuests:kell:greeting": "Um bom couro tem uma história. Me traga um.",
  "tavernGuests:sefra:role": "Joalheira",
  "tavernGuests:sefra:greeting": "Uma pedra carrega o tempo que fez. Lapide-a direito.",
  "tavernGuests:orin:role": "Criador de runas",
  "tavernGuests:orin:greeting": "O véu está rasgando lá em cima. Costure algo que aguente.",
  "tavernGuests:wenna:role": "Encantadora",
  "tavernGuests:wenna:greeting": "Os mortos não perguntam o preço. Eu pergunto.",
  "tavernGuests:pim:role": "Ladrão",
  "tavernGuests:pim:greeting": "Ninguém sente falta do que nunca contou.",
  "tavernGuests:torvald:role": "Construtor",
