  "items:kestrel_loop:name": "Anel do Peneireiro",
  "items:kestrel_loop:description": "Um anel fino trabalhado com a pena primária de um peneireiro, ainda levemente untada da última caçada.",
  "items:hawkeye_gyre:name": "Faixa do Olho de Falcão",
  "items:hawkeye_gyre:description": "Cravejada com um fragmento de rubi polido, lapidado como o olho vigilante de um falcão. Firma a mão que estica o arco.",
  "items:sinewbound_coil:name": "Anel Atado em Tendão",
  "items:sinewbound_coil:description": "Amarrado com tendão seco sobre uma pedra ensanguentada. Quem o usa afirma que ele zumbe de leve antes de a corda ser solta.",
  "items:windwidow_snare:name": "Selo da Viúva do Vento",
  "items:windwidow_snare:description": "Batizado em homenagem a uma caçadora que sobreviveu a todo alvo que já flechou. O diamante nunca reflete a luz de frente.",
  "items:blackfletch_nock:name": "Anel de Pena Negra",
  "items:blackfletch_nock:description": "Ônix cravejado em couro de guerra, emplumado de preto para desaparecer contra um céu noturno. A resposta dos arqueiros ao anel de ônix dos espadachins.",
  "items:ghostquiver_notch:name": "Faixa da Aljava Fantasma",
  "items:ghostquiver_notch:description": "Envolta em couro de dragão empalidecido pelos anos. Quem a usa diz que a aljava nas costas parece mais leve, embora nunca seja.",
  "items:worldpiercer_barb:name": "Anel do Perfuramundos",
  "items:worldpiercer_barb:description": "Gema divina cravejada em pele sombria sobre um aro de aetério. Dizem que atravessou com uma flecha algo que não deveria ter um outro lado.",
  "items:longsight_cord:name": "Cordão da Vista Longa",
  "items:longsight_cord:description": "Um cordão de couro enfiado com fragmentos de safira. Usado por batedores que aprenderam a confiar mais nos olhos do que nas pernas.",
  "items:windwhisper_torc:name": "Torque do Sussurro do Vento",
  "items:windwhisper_torc:description": "Um torque de couro escamado cravejado com rubi. Cavaleiros juram que ele carrega o som do voo de uma flecha um batimento antes do impacto.",
  "items:harriers_clasp:name": "Corrente do Falcão Estrangulador",
  "items:harriers_clasp:description": "Couro rebitado enfiado com pedra de sangue, batizado em homenagem a uma ave que nunca erra seu segundo ataque.",
  "items:kitehunter_collar:name": "Pingente do Caçador de Milhafres",
  "items:kitehunter_collar:description": "Diamante cravejado em couro rebitado e fio de mithril. Permanece firme mesmo em plena corrida.",
  "items:gloomfletch_choker:name": "Amuleto de Pena Sombria",
  "items:gloomfletch_choker:description": "Ônix preso em couro de guerra escuro, emplumado com penas que parecem beber a luz ao redor. A resposta dos arqueiros ao amuleto de ônix.",
  "items:nightquarry_wreath:name": "Corrente da Presa Noturna",
  "items:nightquarry_wreath:description": "Pedra do vazio enrolada em couro de dragão e ferro enegrecido. Troféus tomados ao luar nunca parecem os mesmos de dia.",
  "items:deadeye_reliquary:name": "Relicário do Olho Certeiro",
  "items:deadeye_reliquary:description": "Um relicário de gema divina cravejado em pele sombria sobre aetério. Guarda a última mira de uma arqueira que nunca precisou de uma segunda flecha.",

