  "items:emberglass_loop:name": "Anel de Vidro de Brasa",
  "items:emberglass_loop:description": "Um fragmento de fogo engastado atrás de um vidro que o calor antigo tornou âmbar. Aquece a mão antes mesmo de qualquer feitiço ser lançado.",
  "items:hollowlight_seal:name": "Selo de Luz Oca",
  "items:hollowlight_seal:description": "Um fragmento de Aether selado em mithril, que brilha fracamente mesmo em plena luz do dia. O primeiro anel de que um mago não precisa se envergonhar.",
  "items:nightwell_loop:name": "Anel do Poço Noturno",
  "items:nightwell_loop:description": "Ônix enrolado em torno de um fragmento do vazio, tirando seu brilho de algo mais escuro que a luz da lua. Batizado em homenagem a um poço que nenhuma tocha jamais iluminou.",
  "items:voidscribe_glyph:name": "Bracelete do Escriba do Vazio",
  "items:voidscribe_glyph:description": "Uma pedra do vazio gravada com um glifo que se reescreve sozinho quando ninguém está olhando. Quem o usa aprende a não lê-lo com atenção demais.",
  "items:godsight_loop:name": "Anel da Visão Divina",
  "items:godsight_loop:description": "Uma gema divina engastada em prata abençoada, que dizem mostrar a quem a usa uma verdade antes de cada feitiço. Poucos afirmam gostar do que veem.",
  "items:ashcant_cord:name": "Pingente do Cântico de Cinzas",
  "items:gravecall_sigil:name": "Amuleto do Chamado da Sepultura",
  "items:duskveil_wreath:name": "Corrente do Véu Crepuscular",
  "items:duskveil_wreath:description": "Ônix envolto em runito e tecido fantasma, que dizem escurecer um pouco o ambiente onde quer que seja usado.",
  "items:voidsong_locket:name": "Amuleto do Canto do Vazio",
  "items:voidsong_locket:description": "Um relicário de pedra do vazio que entoa uma nota que mais ninguém consegue ouvir. Conjuradores juram que ele acompanha exatamente o ritmo de seu próprio pulso.",
  "items:godgem_reliquary:name": "Relicário de Gema Divina",
  "items:godgem_reliquary:description": "Um relicário de gema divina entrelaçado com tecido estelar, guardando o último escudo de uma conjuradora que nunca precisou de um segundo.",

