  "items:bloodiron_locket:name": "Medalhão de Ferro-Sangue",
  "items:warcrown_reliquary:name": "Relicário da Coroa de Guerra",
  "items:warcrown_reliquary:description": "Um relicário de gema divina engastado duas vezes em ferro divino, guardando a coroa de um senhor da guerra que nunca precisou erguê-la em sua defesa.",
  "items:cutthroat_loop:name": "Anel do Degolador",
  "items:cutthroat_loop:description": "Um anel de dentes de chacal, usado por caçadores que esperam uma ferida se abrir antes de atacar. Recompensa o golpe que encerra tudo.",
  "items:firstlight_seal:name": "Selo da Primeira Luz",
  "items:firstlight_seal:description": "Forjado da primeira brasa de um fogo de forja. Toda luta se decide no primeiro golpe, ou não se decide de jeito nenhum.",
  "items:tidewrack_collar:name": "Corrente dos Destroços da Maré",
  "items:hollowmarch_notch:name": "Faixa da Marcha Oca",
  "items:hollowmarch_notch:description": "Alisada por uma marcha sem fim através de salões ocos. Fica mais forte a cada passo que não para.",
  "items:ashenvow_locket:name": "Pingente do Voto de Cinzas",
  "items:ashenvow_locket:description": "Um voto jurado sobre brasas ardentes, mantido mesmo quando a chama se apagou. Golpeia mais forte com o último fôlego nos pulmões.",
  "items:rimeheart_locket:name": "Medalhão de Coração Gélido",
  "items:rimeheart_locket:description": "Congelado por completo por uma maga do gelo que nunca sentiu o frio. Pune tudo que já é lento demais para fugir.",
  "items:thornwarden_seal:name": "Selo do Guardião Espinhoso",
  "items:thornwarden_seal:description": "Esculpido por um guardião que transformava cada golpe recebido no próximo que desferia. Recompensa o lutador que ainda está de pé.",
  "items:sunder_crown:name": "Coroa Estilhaçada",
  "items:sunder_crown:description": "Estilhaçada de uma coroa que não governava reino algum, usada por quem domina todas as artes ao mesmo tempo. Um golpe fatal acerta mais forte quando poderia ter vindo de qualquer lugar.",

