  "items:oreveined_hoop:name": "Anel Veio de Minério",
  "items:oreveined_hoop:description": "Cravejado com um fragmento de safira sobre minério bruto, ainda com um leve cheiro do veio de onde foi extraído. Dobra o rendimento de um golpe, de vez em quando.",
  "items:thriftcut_cinch:name": "Anel do Corte Econômico",
  "items:thriftcut_cinch:description": "Um diamante engastado em mithril, alisado por mãos que nunca desperdiçaram um único corte de couro.",
  "items:steadhand_cuff:name": "Anel da Mão Firme",
  "items:steadhand_cuff:description": "Ônix preso em fio tocado pelo vazio. Impede que a mão trema bem no momento em que mais importa.",
