  "dungeons:expunged_chapel:waveMeta.2.name": "O Expurgador",
  "quests:chronicle_22:name": "O Salão Vazio",
  "quests:chronicle_23:name": "A Consagração",
  "quests:chronicle_24:name": "O que os ídolos beberam",
  "quests:chronicle_25:name": "As Guirlandas",
  "quests:chronicle_25:loreText": "Eu os vi serem fundidos, no Poço de Escória, quando ainda acreditava que alertar era uma profissão. As primeiras guirlandas de ferro divino, guiadas por mãos que não eram humanas. Aqui estão de novo. Os Portadores de Guirlandas caminham em procissão pelo longo salão, ombro a ombro, carregando o que lhes puseram como se a procissão ainda não tivesse terminado. Ninguém lhes disse para onde vão. Isso nunca foi decidido. Você se pôs no caminho deles, e eles caíram como caem as obras: sem queixa, com muito barulho. Estudei as rebarbas de fundição nos cacos até minha mão ficar firme. Rebarbas são removidas quando uma obra está pronta. Estas nunca ficaram prontas. Isso me alivia de um jeito que prefiro não explicar.",
  "quests:chronicle_26:name": "Obras de cerco",
  "quests:chronicle_26:loreText": "Os ídolos eram suas obras de cerco contra o céu. Anotei a frase quando Drazhan a disse, e só hoje entendi que ele falava literalmente. No fim do Salão eles estão em fila, curvados para o céu, os braços refundidos como braços de arremesso, inacabados e sem mestre. O que deviam atingir continua em silêncio. Prefiro que ninguém os termine. Você os derrubou um após o outro, e quando o último tombou, a parede atrás deles ficou livre. Uma porta que não está em nenhuma planta do Salão, e eu tenho as plantas. Além dela, uma ala em que cada inscrição foi cinzelada até sumir, com limpeza, linha por linha. Alguém tem trabalhado aqui. Não creio que ele tenha terminado.",
  "quests:chronicle_27:name": "O Expurgador",
  "quests:chronicle_27:description": "Limpe a Capela Expurgada e derrube o Expurgador: o que cortou as escrituras ainda está trabalhando.",
  "quests:chronicle_27:loreText": "A procissão na entrada, a lacuna atrás dela e, no fundo da capela, ele. Ele não ergueu os olhos quando você chegou. Estava cinzelando. O Expurgador é a mão que cortou o nome do Sétimo das escrituras, e ela não parou de cortar, porque um nome pode voltar se você deixar. Você o derrubou, e o trabalho dele ficou onde estava: paredes cheias de lacunas, todas com a mesma forma. Percorri uma com a mão. Ela se encaixa na lacuna para a qual os sacerdotes rezam. Escrevo isto com sobriedade, porque não sei escrever de outro jeito: o Sétimo não foi esquecido. Ele é mantido esquecido. Quem quer isso não está em nenhum livro que eu possua — ainda não. As Guerras dos Deuses não começam com deuses. Começam com aquilo que alguém quis expurgar.",
  "achievements:ach_chapter_22:name": "O Salão Vazio",
  "achievements:ach_chapter_22:description": "Conclua o capítulo 22 da Crônica: O Salão Vazio.",
  "achievements:ach_chapter_23:name": "A Consagração",
  "achievements:ach_chapter_23:description": "Conclua o capítulo 23 da Crônica: A Consagração.",
  "achievements:ach_chapter_24:name": "O que os ídolos beberam",
