  "achievements:ach_chapter_25:name": "As Guirlandas",
  "achievements:ach_chapter_25:description": "Conclua o capítulo 25 da Crônica: As Guirlandas.",
  "achievements:ach_chapter_26:name": "Obras de cerco",
  "achievements:ach_chapter_26:description": "Conclua o capítulo 26 da Crônica: Obras de cerco.",
  "achievements:ach_chapter_27:name": "Mantido esquecido",
